"""Column-level decisions (keep / maybe / drop) with reasons. Every one of the 84 raw columns is listed.
role: feature | target-component | leakage | id | geo-key | split-key | dropped
tier (for kept features): A = known at / shortly after first notice of loss (policy, property, location, date);
                          B = adjuster-assessed after inspection (damage, depth, value) -> not available at notice
derived: engineered column(s) in cleaned_claims that replace the raw column."""
D = {}
def add(col, decision, reason, role, derived=""): D[col] = dict(decision=decision, reason=reason, role=role, derived=derived)

add("agricultureStructureIndicator","drop","near-constant (99.97% False)","dropped")
add("asOfDate","drop","constant (single snapshot timestamp 2026-09-08)","dropped")
add("basementEnclosureCrawlspaceType","keep","structure/exposure info; 48.7% missing -> kept as explicit 'unknown' category (missing is not random)","feature","basement_type")
add("policyCount","keep","insured units on the record (RCBAP condos >1); extremely right-skewed -> clipped + log1p","feature","log_policy_count")
add("crsClassCode","keep","community CRS class (1-10); 29.8% missing -> 'unknown' category + ordinal","feature","crs_class")
add("dateOfLoss","keep","time key; used for split and for seasonality features (month sin/cos), not as raw date","split-key","loss_month, loss_month_sin, loss_month_cos, loss_dow")
add("elevatedBuildingIndicator","keep","building elevated per NFIP definition; no missing","feature","elevated_building")
add("elevationCertificateIndicator","drop","87.7% missing (>60%); availability kept as flag","dropped","has_elevation_cert")
add("elevationDifference","drop","65.8% missing (>60%), outliers/sentinels (e.g. -9980, 987); availability kept as flag","dropped","has_elevation_data")
add("baseFloodElevation","drop","66.0% missing (>60%), sentinel 9990, absolute elevation acts as a location proxy","dropped","has_elevation_data")
