add("lowestAdjacentGrade","drop","64.5% missing (>60%), sentinels (+/-9999), absolute elevation = location proxy","dropped","has_elevation_data")
add("lowestFloorElevation","drop","64.2% missing (>60%), sentinels (+/-9999), absolute elevation = location proxy","dropped","has_elevation_data")
add("numberOfFloorsInTheInsuredBuilding","keep","building height code; 0.12% missing -> mode","feature","num_floors_code")
add("nonProfitIndicator","drop","near-constant (99.2% False)","dropped")
add("obstructionType","drop","78.4% missing (>60%); only defined for elevated buildings","dropped")
add("occupancyType","keep","occupancy code; legacy 1-digit codes harmonised to Risk Rating 2.0 2-digit codes","feature","occupancy_std")
add("originalConstructionDate","keep","converted to building age at loss; invalid dates (<1850, after loss) set missing; 55% are Jan-1 placeholders","feature","building_age, construction_date_jan1")
add("originalNBDate","keep","converted to policy tenure at loss; dates after loss / before 1968 invalid -> missing","feature","policy_tenure_years")
add("amountPaidOnBuildingClaim","keep","TARGET COMPONENT (gross building payment); NaN (7.8%) means claim closed with no payment (net payment is 0 in 100% of those rows) -> 0","target-component","paid_building")
add("amountPaidOnContentsClaim","keep","TARGET COMPONENT (gross contents payment); NaN -> 0 as above","target-component","paid_contents")
add("amountPaidOnIncreasedCostOfComplianceClaim","drop","99.6% zeros; payment (post-outcome) - not a feature; kept only as paid_icc for reference","leakage","paid_icc")
add("postFIRMConstructionIndicator","keep","built after FIRM / 1974 (rating & code-compliance proxy); no missing","feature","post_firm")
add("rateMethod","keep","rating method; 'RE' = Risk Rating 2.0 (90% of rows); collapsed to 6 groups","feature","rating_group, is_rr2")
add("smallBusinessIndicatorBuilding","maybe","97.3% False - weak but non-trivial; kept as binary","feature","small_business")
