add("totalContentsInsuranceCoverage","keep","policy contents limit (0 = no contents cover); log1p; flag no_contents_cov","feature","log_cont_coverage, no_contents_cov")
add("yearOfLoss","keep","identical to year(dateOfLoss); used as split/grouping key only (a trend variable would not generalise)","split-key","loss_year")
add("primaryResidenceIndicator","keep","primary residence flag; no missing","feature","primary_residence")
add("buildingDamageAmount","maybe","TIER B: adjuster-assessed ACV damage; strongest driver of payout but only known after inspection (leakage if the goal is early triage); 0 is valid, 11% NaN","feature","log_bldg_damage, bldg_damage_missing")
add("buildingDeductibleCode","keep","deductible code mapped to USD; 2.4% missing -> 'unknown' flag + mode","feature","bldg_deductible_usd, bldg_deductible_missing")
