add("numberOfUnits","maybe","units under condo master policy; max 34,970 -> clipped at p99.9; mostly 0/1 so weak","feature","log_num_units")
add("buildingReplacementCost","maybe","TIER B: insurer-estimated replacement cost; strongly collinear with buildingPropertyValue; 0 -> missing","feature","log_repl_cost")
add("contentsReplacementCost","drop","redundant with contentsPropertyValue/coverage; 37.8% missing; extreme skew","dropped")
